head.script:
scwin.onpageload = function () {
	let specialChar = '·'; //return 2
	let websquareBytes = WebSquare.util.getStringByteSize(specialChar);
	console.log(`${specialChar}문자 예상 결과 : 2, 실제 결과 : `, websquareBytes);
};

scwin.input1_onblur = function (e) {
	let inputVal = input1.getValue();
	let websquareBytes = WebSquare.util.getStringByteSize(inputVal);
	console.log(`실제 결과 : `, websquareBytes);
};
